        [Test]public void EighteenLampsBelongToThreeInactiveRoomsAndMainHasNoLampAssetReferences()
        {
            var previous=SceneManager.GetActiveScene();for(int i=0;i<3;i++){var scene=EditorSceneManager.OpenScene(NextRoomPartition.RoomPath(i),OpenSceneMode.Additive);try{var room=scene.GetRootGameObjects().Single();Assert.That(room.activeSelf,Is.False);var lamps=room.GetComponent<InstancedRoomLamps>();Assert.That(lamps.InstanceCount,Is.EqualTo(6));Assert.That(lamps.View,Is.Null);Assert.That(AssetDatabase.GetAssetPath(lamps.SharedMesh),Is.EqualTo(NextLampAssets.MeshPath));Assert.That(room.GetComponentsInChildren<MeshRenderer>(true).Length,Is.EqualTo(i==0?13:12));Assert.That(room.GetComponentsInChildren<Collider>(true),Is.Empty);Assert.That(room.GetComponentsInChildren<Light>(true),Is.Empty);}finally{SceneManager.SetActiveScene(previous);EditorSceneManager.CloseScene(scene,true);}}var dependencies=AssetDatabase.GetDependencies(NextRoomPartition.Main,true);foreach(var asset in new[]{NextLampAssets.MeshPath,NextLampAssets.BodyPath,NextLampAssets.LightPath})Assert.That(dependencies,Does.Not.Contain(asset));var group=NextAddressables.Settings.groups.Single(g=>g&&g.Name==NextLampStreamingSetup.Group);Assert.That(group.entries.Count,Is.EqualTo(3));
        }
        Scene previousScene,main;bool background;int bundles;RoomSceneOwner owner;NextRoomStreaming stream;Camera camera;JArray details;Volume volume;VolumeProfile profile;
        void Received(JArray events)=>details=events;
        static IEnumerator Wait(Func<bool> condition,string stage){var timer=System.Diagnostics.Stopwatch.StartNew();while(!condition()){Assert.That(timer.Elapsed.TotalSeconds,Is.LessThan(15),stage);yield return null;}}
        void Render(){for(int i=0;i<3;i++)if(stream.Room(i)){var lamps=stream.Room(i).GetComponent<InstancedRoomLamps>();if(lamps.enabled)lamps.Submit(camera);}using(var image=new SalvageFrameCapture(camera))image.Capture(NextLampStreamingSetup.Evidence+"/FDImage_Runtime.png");}
        [UnityTest,Timeout(180000)]public IEnumerator RealBundleLightsBindPlayerCameraRenderInstancedAndReleaseSharedMeshAfterLastRoom()
        {
            yield return new EnterPlayMode();background=Application.runInBackground;Application.runInBackground=true;bundles=AssetBundle.GetAllLoadedAssetBundles().Count();previousScene=SceneManager.GetActiveScene();main=EditorSceneManager.LoadSceneInPlayMode(NextRoomPartition.Main,new LoadSceneParameters(LoadSceneMode.Additive));while(!main.isLoaded)yield return null;SceneManager.SetActiveScene(main);var root=main.GetRootGameObjects().Single(r=>r.name=="ES_SalvageNext_World");stream=root.GetComponentInChildren<NextRoomStreaming>();owner=stream.Owner;var motor=stream.GetComponent<SalvageMotor>();motor.enabled=false;var echo=root.GetComponentInChildren<SalvageEcho>();var brain=echo.GetComponent<SalvageEchoCoordinator>();brain.enabled=false;brain.AutomaticWarnings=false;Assert.That(brain.Initialize(),Is.True);brain.ResetBase(IntentKind.Wait);yield return Wait(()=>owner.IsReady(0)&&owner.IsReady(1)&&!stream.Blocking,"Actual room lamps ready");var a=stream.Room(0).GetComponent<InstancedRoomLamps>();var b=stream.Room(1).GetComponent<InstancedRoomLamps>();camera=motor.View.GetComponent<Camera>();Assert.That(a.View,Is.SameAs(camera));Assert.That(b.View,Is.SameAs(camera));var mesh=a.SharedMesh;var light=a.MaterialAt(1);Assert.That(mesh,Is.SameAs(b.SharedMesh));Assert.That(light,Is.SameAs(b.MaterialAt(1)));Assert.That(AssetDatabase.GetAssetPath(mesh),Is.Empty);Assert.That(AssetDatabase.GetAssetPath(light),Is.Empty);Assert.That(light.IsKeywordEnabled("_EMISSION"),Is.True);
            var labels=stream.GetComponent<NextWorldLabels>();labels.enabled=false;foreach(var text in root.GetComponentsInChildren<TextMesh>())text.GetComponent<Renderer>().enabled=false;stream.GetComponent<NextFocus>().enabled=false;root.GetComponent<NextFogField>().enabled=false;foreach(var lamp in root.GetComponentsInChildren<Light>())lamp.enabled=false;foreach(var flicker in root.GetComponentsInChildren<EchoStation.Rendering.FaultLightFlicker>())flicker.enabled=false;volume=root.GetComponentsInChildren<Volume>().Single(v=>v.name=="ES_Next_GlobalVolume");profile=volume.profile;profile.TryGet<FilmGrain>(out var grain);grain.intensity.value=0;profile.TryGet<ChromaticAberration>(out var chromatic);chromatic.intensity.value=0;camera.transform.position=new Vector3(6,1.4f,12);camera.transform.LookAt(new Vector3(6,2.91f,12),Vector3.forward);camera.fieldOfView=140;a.enabled=b.enabled=false;for(int f=0;f<3;f++)yield return null;string id=Guid.NewGuid().ToString("N");Color[] warm,off,on;using(var image=new SalvageFrameCapture(camera)){warm=image.Capture(NextLampStreamingSetup.Evidence+"/Warm_"+id+".png");off=image.Capture(NextLampStreamingSetup.Evidence+"/Off_"+id+".png");}a.enabled=b.enabled=true;a.Submit(camera);b.Submit(camera);using(var image=new SalvageFrameCapture(camera))on=image.Capture(NextLampStreamingSetup.Evidence+"/On_"+id+".png");float difference=SalvageFrameCapture.Difference(off,on);Assert.That(difference,Is.GreaterThan(.0001f));yield return NextFrameEvidence.Capture(Render,NextLampStreamingSetup.Evidence+"/FD_"+id+".json",Received);int instanced=details.Count(e=>e["type"].Value<string>()=="InstancedMesh"&&e["instances"].Value<int>()>=2&&e["shader"].Value<string>()=="Universal Render Pipeline/Lit");Assert.That(instanced,Is.GreaterThanOrEqualTo(2),details.ToString());
            motor.RestorePose(new Vector3(34,.1f,12),90,0);Assert.That(echo.Navigation.Agent.Warp(new Vector3(33,0,12)),Is.True);stream.EvaluateNow();yield return Wait(()=>owner.IsReady(2)&&owner.Phase(0)==RoomScenePhase.Empty,"Room zero retired");Assert.That(a==null,Is.True);Assert.That(mesh!=null&&light!=null,Is.True);Assert.That(stream.Room(2).GetComponent<InstancedRoomLamps>().SharedMesh,Is.SameAs(mesh));Assert.That(stream.Room(2).GetComponent<InstancedRoomLamps>().View,Is.SameAs(camera));SceneManager.SetActiveScene(previousScene);var unload=SceneManager.UnloadSceneAsync(main);while(!unload.isDone)yield return null;main=default;yield return Wait(()=>owner.IsClosed&&Resources.FindObjectsOfTypeAll<RoomScenePump>().Length==0,"Final lamp group released");Assert.That(mesh==null&&light==null,Is.True);Assert.That(AssetBundle.GetAllLoadedAssetBundles().Count(),Is.EqualTo(bundles));Assert.That(owner.Failures,Is.Zero,owner.LastError);File.WriteAllText(NextLampStreamingSetup.Evidence+"/Runtime_"+id+".json",new JObject{{"actualProvider","BundledSceneProvider"},{"onOffDifference",difference},{"nativeInstancedEvents",instanced},{"firstUnloadKeptShared",true},{"lastUnloadDestroyedMeshAndMaterial",true},{"cameraBindings",true},{"newRealtimeLights",0},{"liveHandles",owner.LiveHandles},{"bundlesAfter",bundles}}.ToString());
        }
        [UnityTearDown]public IEnumerator Cleanup(){if(!Application.isPlaying)yield break;if(volume)volume.profile=null;if(profile){foreach(var c in profile.components)if(c)Object.Destroy(c);Object.Destroy(profile);}if(previousScene.IsValid())SceneManager.SetActiveScene(previousScene);if(main.IsValid()&&main.isLoaded){var unload=SceneManager.UnloadSceneAsync(main);while(unload!=null&&!unload.isDone)yield return null;}if(owner!=null)yield return Wait(()=>owner.IsClosed&&Resources.FindObjectsOfTypeAll<RoomScenePump>().Length==0,"Lamp streaming cleanup");Application.runInBackground=background;yield return new ExitPlayMode();}
    }
